package expo.modules.nativeguide

import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * GuideGeometry against hand-worked cases, and against the TypeScript the React Native rows use: the resource
 * `geometry-fixture.json` holds that TypeScript's own results for the same inputs (generated by
 * `scripts/gen-geometry-fixture.ts` from `features/guide/geometry.ts`), so the two renderers can't drift. Its shape:
 *
 *   { "cells":     [{ "in": { startMs, durationSeconds, originMs, ppm, laneW, gap }, "out": { left, width } | null, "kept": boolean }],
 *     "liveFills": [{ "in": { nowX, left, width }, "out": number }],
 *     "artBoxes":  [{ "in": { w, h, ratio, step }, "out": { w, h } }] }
 *
 * The TypeScript fixes the window (WINDOW_MIN) and the artwork cap (ART_MAX), so the fixture doesn't carry them and
 * the parity tests below pass the same constants. A missing fixture fails these tests rather than skipping them.
 */
class GuideGeometryTest {
  private val min = 60_000L

  // Hand-worked setup: a 180 minute window starting at t = 0, a 600 dp lane (ppm = 600 / 180), a 3 dp gap.
  private val laneW = 600.0
  private val ppm = laneW / 180
  private fun box(startMin: Double, durationSeconds: Int, gap: Double = 3.0) =
    GuideGeometry.cellBox((startMin * min).toLong(), durationSeconds, 0.0, 180.0, ppm, laneW, gap)

  @Test fun aCellInsideTheWindowSitsAtItsStartMinute() {
    val b = box(30.0, 1800)!! // 30 min at 30 min -> left 100, width 100 - gap
    assertEquals(30 * ppm, b.left, 1e-9)
    assertEquals(30 * ppm - 3.0, b.width, 1e-9)
  }

  @Test fun aCellThatBeganBeforeTheTimelineIsClampedToTheGap() {
    val b = box(-10.0, 3600)!! // 60 min starting 10 min early: left clamps to the gap, the right edge stays put
    assertEquals(3.0, b.left, 1e-9)
    assertEquals(50 * ppm - 3.0 - 3.0, b.width, 1e-9)
  }

  @Test fun aCellThatEndedBeforeTheTimelineIsCulled() {
    assertNull(box(-30.0, 1800)) // ends exactly at the origin: end > 0 fails
    assertNull(box(-60.0, 1800))
  }

  @Test fun aCellStartingAtOrPastTheWindowsEndIsCulled() {
    assertNull(box(180.0, 1800))
    assertNull(box(200.0, 1800))
    assertNotNull(box(179.0, 3600)) // starts inside: drawn (its right edge runs past the lane and is clipped by the lane)
  }

  @Test fun aSliverNarrowerThanTheMinimumIsCulled() {
    // 1 min = 3.33 dp, minus the 3 dp gap: wider than the lane-share floor (12 dp) only by the floor itself.
    val floor = laneW * GuideGeometry.MIN_CELL_LANE_SHARE
    val b = box(60.0, 30)!! // 30 s: the floor (12 dp) applies, 12 - 3 = 9 >= 8
    assertEquals(floor - 3.0, b.width, 1e-9)
    assertNull(GuideGeometry.cellBox(60 * min, 30, 0.0, 180.0, ppm, laneW, gap = 5.0)) // 12 - 5 = 7 < 8
  }

  @Test fun aBiggerGapNarrowsEveryCell() {
    assertEquals(box(30.0, 1800, gap = 3.0)!!.width - 2.0, box(30.0, 1800, gap = 5.0)!!.width, 1e-9)
  }

  @Test fun theFilterCullsWithItsOwnGapNotTheCellsGap() {
    // Android TV: cells are placed with a 3 dp gap, but the React Native rows' channel filter has always culled with 6.
    // A program clamped at the rail with 16 dp of it left (4 dp per minute: it ends 4 minutes in) is a 10 dp cell at
    // gap 3, yet the filter drops it, so the native view must not draw it either.
    val startMs = (-10 * min)
    assertEquals(10.0, GuideGeometry.cellBox(startMs, 14 * 60, 0.0, 180.0, 4.0, 720.0, 3.0)!!.width, 1e-9)
    assertFalse(GuideGeometry.isVisible(startMs, 14 * 60, 0.0, 180.0, 4.0, 720.0))
    val g = GuideGeo("""{"rowH": 84.5, "railW": 100, "laneW": 720, "ppm": 4, "originMs": 0, "windowMin": 180, "gap": 3}""")
    assertNull(g.cellBox(GuideProgram("sliver", startMs, 14 * 60, "T", null, "")))
    // A program with room to spare is kept and placed at the cells' gap.
    val kept = g.cellBox(GuideProgram("kept", startMs, 20 * 60, "T", null, ""))!!
    assertEquals(3.0, kept.left, 1e-9)
    assertEquals(10 * 4.0 - 3.0 - 3.0, kept.width, 1e-9)
    assertTrue(GuideGeometry.isVisible(startMs, 20 * 60, 0.0, 180.0, 4.0, 720.0))
  }

  @Test fun theLiveFillRunsFromZeroToOne() {
    val cell = box(30.0, 3600)!! // 30..90 min
    fun fill(nowMin: Double) = GuideGeometry.liveFill(nowMin * min, 0.0, ppm, cell.left, cell.width)
    assertEquals(0.0, fill(10.0), 0.0) // before the cell: clamped to 0
    assertEquals(0.0, fill(30.0), 1e-9)
    assertEquals((60 * ppm - cell.left) / cell.width, fill(60.0), 1e-9)
    assertEquals(1.0, fill(140.0), 0.0) // past the cell: clamped to 1
  }

  @Test fun aProgramIsLiveFromItsStartUntilItsEnd() {
    assertFalse(GuideGeometry.isLive(1000, 60, 999.0))
    assertTrue(GuideGeometry.isLive(1000, 60, 1000.0))
    assertTrue(GuideGeometry.isLive(1000, 60, 60_999.0))
    assertFalse(GuideGeometry.isLive(1000, 60, 61_000.0))
  }

  @Test fun visibleRowsIncludePartialRows() {
    assertEquals(0..6, GuideGeometry.visibleRows(0.0, 88.0, 616.0, 50))
    assertEquals(0..7, GuideGeometry.visibleRows(10.0, 88.0, 616.0, 50))
    assertEquals(1..8, GuideGeometry.visibleRows(100.0, 88.0, 616.0, 50))
    assertEquals(0..2, GuideGeometry.visibleRows(0.0, 88.0, 616.0, 3))
    assertEquals(47..49, GuideGeometry.visibleRows(50 * 88.0 - 3 * 88.0, 88.0, 3 * 88.0, 50))
  }

  @Test fun visibleRowsOfNothingAreEmpty() {
    assertTrue(GuideGeometry.visibleRows(0.0, 88.0, 616.0, 0).isEmpty())
    assertTrue(GuideGeometry.visibleRows(0.0, 0.0, 616.0, 5).isEmpty())
    assertTrue(GuideGeometry.visibleRows(0.0, 88.0, 0.0, 5).isEmpty())
  }

  @Test fun visibleRowsNeverPointPastTheEnd() {
    // A scroll offset beyond the list (it was clamped before, but must not index out of range regardless).
    val r = GuideGeometry.visibleRows(10_000.0, 88.0, 616.0, 5)
    assertEquals(4..4, r)
    assertEquals(0..0, GuideGeometry.visibleRows(-50.0, 88.0, 10.0, 1))
  }

  @Test fun theListNeverScrollsPastItsEnd() {
    assertEquals(50 * 88.0 - 616.0, GuideGeometry.maxScroll(50, 88.0, 616.0), 0.0)
    assertEquals("a short list doesn't scroll", 0.0, GuideGeometry.maxScroll(3, 88.0, 616.0), 0.0)
    assertEquals(0.0, GuideGeometry.maxScroll(0, 88.0, 616.0), 0.0)
  }

  @Test fun artBoxRoundsUpToTheStepAndCaps() {
    assertEquals(listOf(512, 128), GuideGeometry.artBox(225.0, 55.0, 2.0, 1152, 1080).toList())
    assertEquals("a box is never smaller than drawn", listOf(64, 64), GuideGeometry.artBox(1.0, 1.0, 1.0, 1152, 1080).toList())
    assertEquals(listOf(1152, 1080), GuideGeometry.artBox(2000.0, 2000.0, 2.0, 1152, 1080).toList())
    assertEquals(listOf(64, 64), GuideGeometry.artBox(0.0, 0.0, 2.0, 1152, 1080).toList())
  }

  @Test fun artUrlAppendsTheBoxToTheQuery() {
    val box = intArrayOf(512, 128)
    assertEquals("http://s/img/c1?path=%2Fa&w=512&h=128", GuideGeometry.artUrl("http://s/img/c1?path=%2Fa", box))
    assertEquals("http://s/art.jpg?w=512&h=128", GuideGeometry.artUrl("http://s/art.jpg", box))
  }

  @Test fun geoReadsTheSharedFieldsAndAnyOther() {
    val g = GuideGeo("""{"rowH": 84.5, "railW": 100, "laneW": 600, "ppm": 3.5, "originMs": 1000, "windowMin": 120, "gap": 3, "circle": 32}""")
    assertEquals(84.5, g.rowH, 0.0)
    assertEquals(600.0, g.laneW, 0.0)
    assertEquals(120.0, g.windowMin, 0.0)
    assertEquals(32.0, g.dp("circle"), 0.0)
    assertEquals(0.0, g.dp("missing"), 0.0)
    val p = GuideProgram("p", 1000 + 10 * min, 1800, "T", null, "")
    val b = g.cellBox(p)!!
    assertEquals(10 * 3.5, b.left, 1e-9)
  }

  @Test fun geoDefaultsAreInert() {
    val g = GuideGeo("{}")
    assertEquals(0.0, g.rowH, 0.0)
    assertEquals(180.0, g.windowMin, 0.0)
  }

  // Parity with the TypeScript. WINDOW_MIN and ART_MAX are geometry.ts's constants.
  private val windowMin = 180.0
  private val artMax = 1920

  private val fixture: JSONObject by lazy {
    val text = javaClass.classLoader?.getResource("geometry-fixture.json")?.readText()
    JSONObject(requireNotNull(text) { "geometry-fixture.json is missing from the test resources" })
  }

  private fun near(expected: Double, actual: Double, what: String) = assertEquals(what, expected, actual, 1e-9)

  @Test fun cellBoxMatchesTypeScript() {
    val cases = fixture.getJSONArray("cells")
    assertTrue(cases.length() > 0)
    for (i in 0 until cases.length()) {
      val a = cases.getJSONObject(i).getJSONObject("in")
      val got = GuideGeometry.cellBox(a.getLong("startMs"), a.getInt("durationSeconds"), a.getDouble("originMs"), windowMin, a.getDouble("ppm"), a.getDouble("laneW"), a.getDouble("gap"))
      val kept = GuideGeometry.isVisible(a.getLong("startMs"), a.getInt("durationSeconds"), a.getDouble("originMs"), windowMin, a.getDouble("ppm"), a.getDouble("laneW"))
      assertEquals("case $i kept", cases.getJSONObject(i).getBoolean("kept"), kept)
      if (cases.getJSONObject(i).isNull("out")) {
        assertNull("case $i", got)
        continue
      }
      val o = cases.getJSONObject(i).getJSONObject("out")
      assertNotNull("case $i", got)
      near(o.getDouble("left"), got!!.left, "case $i left")
      near(o.getDouble("width"), got.width, "case $i width")
    }
  }

  @Test fun liveFillMatchesTypeScript() {
    val cases = fixture.getJSONArray("liveFills")
    assertTrue(cases.length() > 0)
    for (i in 0 until cases.length()) {
      val a = cases.getJSONObject(i).getJSONObject("in")
      // The TypeScript takes now's lane position (nowX) directly; origin 0 and 1 dp per minute make this one's `nowMs` equal it.
      val got = GuideGeometry.liveFill(a.getDouble("nowX") * GuideGeometry.MIN_MS, 0.0, 1.0, a.getDouble("left"), a.getDouble("width"))
      near(cases.getJSONObject(i).getDouble("out"), got, "case $i")
    }
  }

  @Test fun artBoxMatchesTypeScript() {
    val cases = fixture.getJSONArray("artBoxes")
    assertTrue(cases.length() > 0)
    for (i in 0 until cases.length()) {
      val a = cases.getJSONObject(i).getJSONObject("in")
      val o = cases.getJSONObject(i).getJSONObject("out")
      val box = GuideGeometry.artBox(a.getDouble("w"), a.getDouble("h"), a.getDouble("ratio"), artMax, artMax, a.getInt("step"))
      assertEquals("case $i w", o.getInt("w"), box[0])
      assertEquals("case $i h", o.getInt("h"), box[1])
    }
  }
}
